import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
/**
 * Discourse 中的用户组“flair”：一个使用用户组颜色的圆角方块，
 * 内含该组的图标。无图标时显示名称首字母；无颜色时使用主题灰色。
 */
export default class GroupFlair extends Component {
  view() {
    const {
      group,
      size = 'normal'
    } = this.attrs;
    const color = group.color();
    const icon = group.icon();
    return m("span", {
      className: `LcoyGroupFlair LcoyGroupFlair--${size}${color ? ' LcoyGroupFlair--colored' : ''}`,
      style: color ? {
        '--group-color': color
      } : undefined,
      "aria-hidden": "true"
    }, icon ? m(Icon, {
      name: icon
    }) : m("span", {
      className: "LcoyGroupFlair-initial"
    }, (group.namePlural() || '?').charAt(0).toUpperCase()));
  }
}
flarum.reg.add('lcoy-roselle', 'forum/features/community/GroupFlair', GroupFlair);