import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import CommunityPage from './CommunityPage';
import GroupFlair from './GroupFlair';
import { communityGroups, groupsEnabled, groupSlug, groupUrl, memberCount } from './groups';
import { t } from '../../utils/settings';

/**
 * Discourse 的用户组列表（/g）：每个组一张卡片，显示符号、
 * 名称和成员数。
 *
 * 用户组已在论坛 payload 中下发——仅当前用户可见的组——因此
 * 该页面不发起任何请求。
 */
export default class GroupsPage extends CommunityPage {
  title() {
    return t('community.groups.title');
  }
  className() {
    return 'LcoyGroupsPage';
  }
  enabled() {
    return groupsEnabled();
  }

  /** 顶部按名称筛选（`groups-header-filters`），仅在浏览器端生效。 */
  filter = '';
  content() {
    const query = this.filter.trim().toLowerCase();
    const groups = communityGroups().filter(group => !query || [group.namePlural(), group.nameSingular(), groupSlug(group)].some(name => (name || '').toLowerCase().includes(query)));
    return m("div", {
      className: "LcoyGroups"
    }, m("h1", {
      className: "sr-only"
    }, t('community.groups.title')), m("div", {
      className: "LcoyGroups-header"
    }, m("input", {
      className: "FormControl LcoyGroups-filter",
      type: "search",
      placeholder: t('community.groups.filter_placeholder'),
      "aria-label": t('community.groups.filter_placeholder'),
      value: this.filter,
      oninput: event => this.filter = event.target.value
    })), groups.length ? m("ul", {
      className: "LcoyGroups-grid"
    }, groups.map(group => this.card(group))) : m("p", {
      className: "LcoyCommunity-empty"
    }, t('community.groups.empty')));
  }

  /**
   * Discourse 的 `group-box`：圆形 flair、大号名称及其下方的 @地址、
   * 角落中的成员数，以及底部的加入状态——在 Flarum 中只有管理员
   * 能把用户加入用户组，因此所有组均为“关闭”。
   */
  card(group) {
    const count = memberCount(group);
    return m("li", {
      key: group.id(),
      className: "LcoyGroups-item"
    }, m(Link, {
      className: "LcoyGroupCard",
      href: groupUrl(group),
      style: group.color() ? {
        '--group-color': group.color()
      } : undefined
    }, m("span", {
      className: "LcoyGroupCard-inner"
    }, m("span", {
      className: "LcoyGroupCard-infoWrapper"
    }, group.icon() && m(GroupFlair, {
      group: group
    }), m("span", {
      className: "LcoyGroupCard-info"
    }, m("span", {
      className: "LcoyGroupCard-details"
    }, m("span", {
      className: "LcoyGroupCard-name"
    }, group.namePlural()), m("span", {
      className: "LcoyGroupCard-mention"
    }, "@", groupSlug(group))), count !== null && m("span", {
      className: "LcoyGroupCard-count",
      title: t('community.groups.members', {
        count
      })
    }, m(Icon, {
      name: "far fa-user"
    }), count))), m("span", {
      className: "LcoyGroupCard-membership"
    }, group.isHidden() ? m("span", {
      className: "LcoyGroupCard-hidden"
    }, m(Icon, {
      name: "far fa-eye-slash"
    }), " ", t('community.groups.hidden')) : m("span", null, m(Icon, {
      name: "fas fa-ban"
    }), " ", t('community.groups.closed'))))));
  }
}
flarum.reg.add('lcoy-roselle', 'forum/features/community/GroupsPage', GroupsPage);